  "/workspaces/MetrAIyux-0S/MCP/magicuidesign-portfolio-5ef12e4/src/lib/pagination.ts": '/**\n * Pagination utilities for blog posts and other content collections\n */\n\nexport interface PaginationOptions {\n  page: number;\n  pageSize: number;\n}\n\nexport interface PaginationResult<T> {\n  items: T[];\n  pagination: {\n    page: number;\n    pageSize: number;\n    totalItems: number;\n    totalPages: number;\n    hasNextPage: boolean;\n    hasPreviousPage: boolean;\n  };\n}\n\n/**\n * Paginate an array of items\n */\nexport function paginate<T>(\n  items: T[],\n  options: PaginationOptions\n): PaginationResult<T> {\n  const { page, pageSize } = options;\n  const totalItems = items.length;\n  const totalPages = Math.ceil(totalItems / pageSize);\n  const startIndex = (page - 1) * pageSize;\n  const endIndex = startIndex + pageSize;\n\n  const paginatedItems = items.slice(startIndex, endIndex);\n\n  return {\n    items: paginatedItems,\n    pagination: {\n      page,\n      pageSize,\n      totalItems,\n      totalPages,\n      hasNextPage: page < totalPages,\n      hasPreviousPage: page > 1,\n    },\n  };\n}\n\n/**\n * Get pagination metadata without slicing the array\n */\nexport function getPaginationMeta(\n  totalItems: number,\n  options: PaginationOptions\n) {\n  const { page, pageSize } = options;\n  const totalPages = Math.ceil(totalItems / pageSize);\n\n  return {\n    page,\n    pageSize,\n    totalItems,\n    totalPages,\n    hasNextPage: page < totalPages,\n    hasPreviousPage: page > 1,\n  };\n}\n\n/**\n * Validate and normalize page number\n */\nexport function normalizePage(page: number | string | undefined, maxPage: number): number {\n  if (typeof page === "string") {\n    const parsed = parseInt(page, 10);\n    if (isNaN(parsed) || parsed < 1) return 1;\n    return Math.min(parsed, maxPage);\n  }\n  if (typeof page === "number") {\n    if (page < 1) return 1;\n    return Math.min(page, maxPage);\n  }\n  return 1;\n}\n\n',
  "/workspaces/MetrAIyux-0S/MCP/magicuidesign-portfolio-5ef12e4/src/lib/remark-code-meta.ts": 'export function remarkCodeMeta() {\n    return (tree: any) => {\n        const walk = (node: any) => {\n            if (!node || typeof node !== "object") return;\n\n            if (node.type === "code") {\n                const meta: string | undefined = node.meta;\n                if (meta) {\n                    node.data ||= {};\n                    node.data.hProperties ||= {};\n\n                    node.data.hProperties["data-meta"] = meta;\n\n                    const titleMatch = meta.match(/title="([^"]+)"/);\n                    if (titleMatch?.[1]) {\n                        node.data.hProperties["data-title"] = titleMatch[1];\n                    }\n                }\n            }\n\n            const children = node.children;\n            if (Array.isArray(children)) {\n                for (const child of children) walk(child);\n            }\n        };\n\n        walk(tree);\n    };\n}\n\n\n',
  "/workspaces/MetrAIyux-0S/MCP/magicuidesign-portfolio-5ef12e4/src/lib/utils.ts": 'import { type ClassValue, clsx } from "clsx";\nimport { twMerge } from "tailwind-merge";\n\nexport function cn(...inputs: ClassValue[]) {\n  return twMerge(clsx(inputs));\n}\n\nexport function formatDate(date: string | Date) {\n  // Use UTC to ensure consistent formatting between server and client\n  const dateObj = typeof date === "string" ? new Date(date) : date;\n  return dateObj.toLocaleDateString("en-US", {\n    year: "numeric",\n    month: "long",\n    day: "numeric",\n    timeZone: "UTC",\n  });\n}\n',
  "/workspaces/MetrAIyux-0S/MCP/magicuidesign-portfolio-5ef12e4/src/mdx-components.tsx": 'import { CodeBlock } from "@/components/mdx/code-block";\nimport { MediaContainer } from "@/components/mdx/media-container";\nimport type { ComponentProps } from "react";\n\ntype CodeProps = ComponentProps<"code"> & {\n  "data-language"?: string;\n};\n\nexport const mdxComponents = {\n  MediaContainer,\n  pre: (props: ComponentProps<"pre">) => <CodeBlock {...props} />,\n  hr: (props: ComponentProps<"hr">) => (\n    <div className="my-10 flex w-full items-center" {...props}>\n      <div\n        className="flex-1 h-px bg-border"\n        style={{\n          maskImage:\n            "linear-gradient(90deg, transparent, black 8%, black 92%, transparent)",\n          WebkitMaskImage:\n            "linear-gradient(90deg, transparent, black 8%, black 92%, transparent)",\n        }}\n      />\n    </div>\n  ),\n  table: (props: ComponentProps<"table">) => (\n    <div className="my-6 border border-border rounded-xl overflow-hidden">\n      <div className="w-full overflow-x-auto">\n        <table\n          className="m-0! w-full min-w-full border-separate border-spacing-0"\n          {...props}\n        />\n      </div>\n    </div>\n  ),\n  code: ({ children, ...props }: CodeProps) => {\n    if (props["data-language"]) {\n      return <code {...props}>{children}</code>;\n    }\n    return (\n      <code\n        className="px-1.5 py-0.5 rounded-md bg-muted/60 dark:bg-muted/40 text-sm font-mono text-foreground/90"\n        {...props}\n      >\n        {children}\n      </code>\n    );\n  },\n} as const;\n\n',
  "/workspaces/MetrAIyux-0S/MCP/magicuidesign-portfolio-5ef12e4/tsconfig.json": '{\n  "compilerOptions": {\n    "lib": [\n      "dom",\n      "dom.iterable",\n      "esnext"\n    ],\n    "allowJs": true,\n    "skipLibCheck": true,\n    "strict": true,\n    "noEmit": true,\n    "esModuleInterop": true,\n    "module": "esnext",\n    "moduleResolution": "bundler",\n    "resolveJsonModule": true,\n    "isolatedModules": true,\n    "jsx": "react-jsx",\n    "incremental": true,\n    "plugins": [\n      {\n        "name": "next"\n      }\n    ],\n    "paths": {\n      "@/*": [\n        "./src/*"\n      ],\n      "content-collections": [\n        "./.content-collections/generated"\n      ]\n    },\n    "target": "ES2017"\n  },\n  "include": [\n    "next-env.d.ts",\n    "**/*.ts",\n    "**/*.tsx",\n    ".next/types/**/*.ts",\n    ".next/dev/types/**/*.ts"\n  ],\n  "exclude": [\n    "node_modules"\n  ]\n}',
